+function mxcEntrypointCandidates(): string[] {
+	const packagedRoots = [
+		// Packaged CLI layout: <package>/bin/cline next to <package>/mxc.
+		dirname(dirname(process.execPath)),
+		cliPlatformPackageDir(),
+	];
