+function existing(paths: Array<string | undefined>): string[] {
+	return [
+		...new Set(paths.filter((path): path is string => Boolean(path))),
+	].filter((path) => existsSync(path));
+}
+
+function buildFilesystemPolicy(mxc: MxcModule, cwd: string) {
+	const home = homedir();
